  function reset() {
    state.simTime = 0;
    state.paused = false;
    state.justReset = true;
    btnPlay.textContent = 'Pause';
    for (var i = 0; i < planets.length; i++) {
      planets[i].angle = planets[i].initAngle;
      planets[i].trail.length = 0;
    }
    for (var m = 0; m < moons.length; m++) {
      moons[m].angle = moons[m].initAngle;
    }
    particles.length = 0;
    lastTs = null;
    elSimTime.textContent = '0.0';
    elParticles.textContent = '0';
  }

  function update(dt) {
      var inst = 1 / dt;
      fpsSmooth = fpsSmooth * 0.9 + inst * 0.1;
    }

    if (!state.paused) {
      if (state.justReset) {
        state.justReset = false;
      } else {
        update(dt);
      }
    }

    render();

    elFps.textContent = String(Math.round(fpsSmooth));
    elSimTime.textContent = (state.justReset ? 0 : state.simTime).toFixed(1);
    elParticles.textContent = String(particles.length);

    requestAnimationFrame(frame);
  }

  btnPlay.addEventListener('click', function () {
    state.paused = !state.paused;
